package com.crypto.laplace.pool;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import lombok.*;
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder @Entity @Table(name="laplace_coin_pool")
public class LaplaceCoinPoolEntity { @Id @Column(length=32) private String symbol; @Enumerated(EnumType.STRING) private LaplaceCoinPoolState state; private BigDecimal lastQuoteVolume; private Instant addedAt, removedAt, pendingRemovalAt; @Enumerated(EnumType.STRING) private LaplaceTrend lastObservedTrend; private Boolean waitingForNewTrend; private Instant lastVolumeScanAt; private String stoppedRawSignalSide, stoppedPositionSide, stoppedPositionId; private Instant stoppedAt; private Boolean reentryBlocked; private String unblockedBySignalSide; private Instant unblockedAt; @Column(name="risky_entry_pending") private Boolean riskyDirectionBlocked; @Column(name="pending_risky_raw_signal") private String blockedRiskyRawSignal; @Column(name="pending_risky_signal_candle_close_time") private Instant blockedRiskySignalCandleCloseTime; private Instant createdAt, updatedAt; @PrePersist void created(){Instant n=Instant.now(); if(createdAt==null)createdAt=n;if(reentryBlocked==null)reentryBlocked=false;if(riskyDirectionBlocked==null)riskyDirectionBlocked=false; updatedAt=n;} @PreUpdate void updated(){updatedAt=Instant.now();} }
